:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --cell-bg: #0f3460;
  --cell-hover: #1a4a7a;
  --win-bg: #e94560;
  --focus: #ffd700;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 18px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  background: var(--card);
  border-radius: 12px;
  padding: 24px;
  max-width: 400px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
  text-align: center;
}

h1 {
  font-size: 1.8rem;
  margin-bottom: 16px;
  color: var(--accent);
  letter-spacing: 1px;
  text-transform: uppercase;
  font-weight: 700;
}

.status {
  font-size: 1.2rem;
  margin-bottom: 20px;
  min-height: 1.5em;
  font-weight: 600;
}

.board {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-bottom: 24px;
  aspect-ratio: 1 / 1;
}

.cell {
  background: var(--cell-bg);
  border: none;
  border-radius: 8px;
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  aspect-ratio: 1 / 1;
  font-family: var(--font);
  line-height: 1;
}

.cell:hover:not(.disabled) {
  background: var(--cell-hover);
}

.cell:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.cell:active:not(.disabled) {
  transform: scale(0.95);
}

.cell.disabled {
  cursor: default;
  opacity: 0.9;
}

.cell.win {
  background: var(--win-bg);
  color: var(--bg);
}

.restart-btn {
  background: var(--accent);
  color: var(--bg);
  border: none;
  border-radius: 8px;
  padding: 12px 32px;
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  font-family: var(--font);
}

.restart-btn:hover {
  background: #ff5a7a;
}

.restart-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.restart-btn:active {
  transform: scale(0.95);
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .cell {
    font-size: 2rem;
  }
  .status {
    font-size: 1rem;
  }
}

const boardEl = document.getElementById('board');
const statusEl = document.getElementById('status');
const restartBtn = document.getElementById('restart');

let board = Array(9).fill('');
let currentPlayer = 'X';
let gameOver = false;
let winLine = [];

const winPatterns = [
  [0,1,2], [3,4,5], [6,7,8],
  [0,3,6], [1,4,7], [2,5,8],
  [0,4,8], [2,4,6]
];

function createBoard() {
  boardEl.innerHTML = '';
  for (let i = 0; i < 9; i++) {
    const cell = document.createElement('button');
    cell.className = 'cell';
    cell.dataset.index = i;
    cell.setAttribute('role', 'gridcell');
    cell.setAttribute('aria-label', `Row ${Math.floor(i/3)+1}, Column ${i%3+1}, empty`);
    cell.addEventListener('click', handleMove);
    boardEl.appendChild(cell);
  }
}

function handleMove(e) {
  const cell = e.currentTarget;
  const index = parseInt(cell.dataset.index);
  if (gameOver || board[index] !== '') return;

  board[index] = currentPlayer;
  cell.textContent = currentPlayer;
  cell.disabled = true;
  cell.classList.add('disabled');
  cell.setAttribute('aria-label', `Row ${Math.floor(index/3)+1}, Column ${index%3+1}, ${currentPlayer}`);

  const win = checkWin();
  if (win) {
    gameOver = true;
    winLine = win;
    highlightWin(win);
    statusEl.textContent = `${currentPlayer} wins!`;
    disableAll();
  } else if (board.every(c => c !== '')) {
    gameOver = true;
    statusEl.textContent = "It's a draw!";
  } else {
    currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
    statusEl.textContent = `${currentPlayer}'s turn`;
  }
}

function checkWin() {
  for (const pattern of winPatterns) {
    const [a, b, c] = pattern;
    if (board[a] && board[a] === board[b] && board[a] === board[c]) {
      return pattern;
    }
  }
  return null;
}

function highlightWin(pattern) {
  pattern.forEach(i => {
    const cell = boardEl.children[i];
    cell.classList.add('win');
  });
}

function disableAll() {
  for (const cell of boardEl.children) {
    cell.disabled = true;
    cell.classList.add('disabled');
  }
}

function restart() {
  board = Array(9).fill('');
  currentPlayer = 'X';
  gameOver = false;
  winLine = [];
  statusEl.textContent = "X's turn";
  createBoard();
}

restartBtn.addEventListener('click', restart);

// Initialize
createBoard();
statusEl.textContent = "X's turn";
